"use client";

/**
 * MFA setup panel (spec 015 v1.3.0, D-AUTH-14 — AC-AUTH-014).
 *
 * Two phases, both 100% product screens (no identity-provider pages):
 *  1. "password" — the user confirms their password (the control plane
 *     proves it with a direct grant and starts the enrollment dance
 *     server-side). Skipped when arriving from the login panel (the dance
 *     already started with the password just typed).
 *  2. "qr"       — the QR (PNG generated by the identity engine, relayed by
 *     the control plane) + the confirmation code. On confirm, the control
 *     plane completes the enrollment and mints the MFA-verified session.
 */
import { useCallback, useEffect, useState } from "react";
import { panelErrorMessage } from "@/lib/panel";
import { Button } from "@/components/ui";

type Phase = "loading" | "password" | "qr";

export function MfaSetupClient({
  org,
  email,
  hasDance,
}: {
  org: string;
  email: string;
  hasDance: boolean;
}) {
  const [phase, setPhase] = useState<Phase>(hasDance ? "loading" : "password");
  const [password, setPassword] = useState("");
  const [totp, setTotp] = useState("");
  const [code, setCode] = useState("");
  const [qr, setQr] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const loadQr = useCallback(async () => {
    setError(null);
    try {
      const res = await fetch("/auth/panel/totp/qr");
      const data = (await res.json()) as {
        status: string;
        qr_png?: string | null;
        reason?: string;
        message?: string;
      };
      if (res.ok && data.status === "ok" && data.qr_png) {
        setQr(data.qr_png);
        setPhase("qr");
        return;
      }
      setError(
        panelErrorMessage(
          data.reason ?? "error",
          data.message ?? "The QR code is not available. Please start again.",
        ),
      );
      setPhase("password");
    } catch {
      setError("The console is unreachable. Check your connection and try again.");
      setPhase("password");
    }
  }, []);

  useEffect(() => {
    if (hasDance) void loadQr();
  }, [hasDance, loadQr]);

  async function startSetup(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setBusy(true);
    try {
      const res = await fetch("/auth/panel/totp/setup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ org, email, password, totp: totp.trim() || null }),
      });
      const data = (await res.json()) as {
        status: string;
        reason?: string;
        message?: string;
      };
      if (res.ok && data.status === "ok") {
        await loadQr();
        return;
      }
      setError(
        panelErrorMessage(
          data.reason ?? "error",
          data.message ?? "Setup could not be started.",
        ),
      );
    } catch {
      setError("The console is unreachable. Check your connection and try again.");
    } finally {
      setBusy(false);
    }
  }

  async function confirmCode(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    if (!code.trim()) {
      setError("Enter the code from your authenticator app.");
      return;
    }
    setBusy(true);
    try {
      const res = await fetch("/auth/panel/totp/confirm", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ code: code.trim() }),
      });
      const data = (await res.json()) as {
        status: string;
        reason?: string;
        message?: string;
      };
      if (res.ok && data.status === "ok") {
        window.location.href = "/overview";
        return;
      }
      setError(
        panelErrorMessage(
          data.reason ?? "error",
          data.message ?? "The code could not be verified.",
        ),
      );
    } catch {
      setError("The console is unreachable. Check your connection and try again.");
    } finally {
      setBusy(false);
    }
  }

  const inputClass =
    "w-full rounded-lg border border-border-subtle bg-surface px-3.5 py-2.5 text-sm text-foreground transition-all duration-150 placeholder:text-muted hover:border-foreground/25 focus:border-foreground/60 focus:outline-none focus:ring-[3px] focus:ring-foreground/[0.12]";

  return (
    <div>
      {error ? (
        <p
          role="alert"
          className="mb-4 rounded-lg border border-danger/25 bg-danger-soft px-4 py-3 text-sm text-danger"
        >
          {error}
        </p>
      ) : null}

      {phase === "loading" ? (
        <p className="text-sm text-muted">Loading your setup code…</p>
      ) : null}

      {phase === "password" ? (
        <form onSubmit={startSetup} className="space-y-4" noValidate>
          <div>
            <label
              htmlFor="password"
              className="mb-2 block text-sm font-medium text-foreground"
            >
              Confirm your password
            </label>
            <input
              id="password"
              type="password"
              autoComplete="current-password"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className={inputClass}
            />
            <p className="mt-1.5 text-xs text-muted">
              We ask for it again to protect your account before adding a
              second factor.
            </p>
          </div>
          <Button type="submit" variant="primary" className="w-full py-2.5" disabled={busy}>
            {busy ? "Starting…" : "Continue"}
          </Button>
        </form>
      ) : null}

      {phase === "qr" ? (
        <div className="space-y-5">
          <ol className="space-y-2 text-sm text-muted">
            <li>
              <span className="font-medium text-foreground">1.</span> Open your
              authenticator app (Google Authenticator, FreeOTP, 1Password…).
            </li>
            <li>
              <span className="font-medium text-foreground">2.</span> Scan this
              code with it.
            </li>
            <li>
              <span className="font-medium text-foreground">3.</span> Enter the
              6-digit code it shows to confirm.
            </li>
          </ol>
          {qr ? (
            <div className="flex justify-center rounded-xl border border-border-subtle bg-white p-4">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={qr}
                alt="Multi-factor setup QR code"
                width={208}
                height={208}
                className="size-52"
              />
            </div>
          ) : null}
          <form onSubmit={confirmCode} className="space-y-4" noValidate>
            <div>
              <label
                htmlFor="code"
                className="mb-2 block text-sm font-medium text-foreground"
              >
                One-time code
              </label>
              <input
                id="code"
                type="text"
                inputMode="numeric"
                autoComplete="one-time-code"
                maxLength={8}
                required
                value={code}
                onChange={(e) => setCode(e.target.value)}
                className={inputClass}
                placeholder="6-digit code"
                autoFocus
              />
            </div>
            <Button type="submit" variant="primary" className="w-full py-2.5" disabled={busy}>
              {busy ? "Verifying…" : "Confirm and finish"}
            </Button>
          </form>
        </div>
      ) : null}
    </div>
  );
}
